import fs from 'node:fs';import path from 'node:path';import http from 'node:http';import assert from 'node:assert/strict';import {createRequire} from 'node:module';
import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261024-guided-review-navigation',site=stage+'/website',dir=stage+'/browser';assert(!fs.existsSync(dir));fs.mkdirSync(dir);
assert.equal(json('CURRENT_CHECKPOINT.json').activeWork.current.activeExecutionSessions.length,0,'Acquire the serial validation slot before building the tiny QA bundle');
const {build}=createRequire(site+'/package.json')('esbuild');
const sequences=[];for(const name of ['head-atlas','head-mri','head-insula','head-orbital','head-ct-bone','head-cerebellar']){
 const api=await import('file:///'+site+'/lib/'+name+'-learning.ts');const list=Object.entries(api).find(([key])=>key.endsWith('LearningSequences'))?.[1];assert(Array.isArray(list));sequences.push(...list.map(sequence=>({id:'head-guided-sequence-'+sequence.id,label:'Guided · '+sequence.label+' · Draft'})));
}
assert.equal(new Set(sequences.map(s=>s.id)).size,sequences.length);
const entry="import React from 'react';import {createRoot} from 'react-dom/client';import {HeadTeachingReviewNavigator} from './components/HeadTeachingReviewNavigator';createRoot(document.getElementById('navigator')).render(React.createElement(HeadTeachingReviewNavigator,{targets:"+JSON.stringify(sequences)+"}));";
const compiled=await build({stdin:{contents:entry,resolveDir:site,loader:'tsx'},bundle:true,write:false,platform:'browser',format:'esm',metafile:true,jsx:'automatic',absWorkingDir:site});
const js=compiled.outputFiles[0].contents;fs.writeFileSync(dir+'/client.js',js,{flag:'wx'});const inputs=Object.keys(compiled.metafile.inputs).filter(p=>p!=='<stdin>').map(p=>{const file=path.resolve(site,p);return{path:file,sha256:hash(file)};});assert(inputs.some(row=>row.path.replaceAll('\\','/').endsWith('/components/HeadTeachingReviewNavigator.tsx')));
const encode=value=>value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const targets=sequences.map((s,index)=>'<details><summary>Closed group '+(index+1)+'</summary>'+ (index%3===0?'<details id="'+s.id+'"><summary>'+encode(s.label)+'</summary><p>Synthetic sequence placeholder.</p></details>':index%3===1?'<section id="'+s.id+'"><h3>'+encode(s.label)+'</h3><p>Synthetic sequence placeholder.</p></section>':'<ol id="'+s.id+'"><li>'+encode(s.label)+'</li></ol>')+'</details>').join('');
const html='<!doctype html><html><head><meta charset="utf-8"><title>Guided review navigation QA</title></head><body><main><h1>Guided review navigation · isolated interaction test</h1><p>Synthetic notes and placeholders only. This is not Clinical Review and records no approval.</p><label>Unsubmitted synthetic note<input id="synthetic-note"></label><div id="navigator"></div>'+targets+'</main><script type="module" src="/client.js"></script></body></html>';
const control='<!doctype html><html><head><meta charset="utf-8"><title>Static diagnostic control</title></head><body><h1>Static diagnostic control</h1><p>No application scripts, frames, styles or Atlas assets are included.</p></body></html>';
fs.writeFileSync(dir+'/navigation.html',html,{flag:'wx'});fs.writeFileSync(dir+'/control.html',control,{flag:'wx'});const requests=[];
const server=http.createServer((req,res)=>{const url=new URL(req.url,'http://qa.invalid');requests.push({at:new Date().toISOString(),method:req.method,path:url.pathname});res.setHeader('Cache-Control','no-store');if(req.method!=='GET'||!['/navigation','/client.js','/control'].includes(url.pathname)){res.writeHead(404);res.end('Not registered');return;}res.setHeader('Content-Type',url.pathname==='/client.js'?'text/javascript;charset=utf-8':'text/html;charset=utf-8');res.end(url.pathname==='/client.js'?js:url.pathname==='/control'?control:html);});
function state(active){const p=json('CURRENT_CHECKPOINT.json');assert.equal(p.activeWork.current.ownerPreviewPolicy.restartPermitted,false);p.activeWork.current.activeExecutionSessions=p.activeWork.current.activeExecutionSessions.filter(r=>r.role!=='guided-review-navigation-qa');if(active)p.activeWork.current.activeExecutionSessions.push({role:'guided-review-navigation-qa',pid:process.pid,evidence:dir,previewChanged:false});const text=JSON.stringify(p,null,2)+'\n';assert(Buffer.byteLength(text)<65536);fs.writeFileSync('CURRENT_CHECKPOINT.json',text);}
const write=(name,value)=>fs.writeFileSync(dir+'/'+name,JSON.stringify(value,null,2)+'\n',{flag:'wx'});let closing=false;function close(reason){if(closing)return;closing=true;server.close(()=>{write('REQUESTS.json',requests);write('TERMINAL.json',{at:new Date().toISOString(),pid:process.pid,reason,code:0,graceful:true,previewChanged:false});state(false);process.exit(0);});}
server.listen(0,'127.0.0.1',()=>{const base='http://127.0.0.1:'+server.address().port;write('STARTED.json',{at:new Date().toISOString(),base,pid:process.pid,component:site+'/components/HeadTeachingReviewNavigator.tsx',componentSha256:hash(site+'/components/HeadTeachingReviewNavigator.tsx'),entry,clientSha256:hash(dir+'/client.js'),inputs,sequences,navigationHtmlSha256:hash(dir+'/navigation.html'),controlHtmlSha256:hash(dir+'/control.html'),syntheticPlaceholdersOnly:true,authenticatedAcceptance:false,noRuntimeModuleSubstitution:true,previewChanged:false});state(true);console.log(JSON.stringify({base,pid:process.pid,quit:'q',sequences:sequences.length}));});
process.stdin.setEncoding('utf8');process.stdin.on('data',value=>{if(value.trim()==='q')close('q');});process.stdin.on('end',()=>close('stdin-ended'));process.on('SIGINT',()=>close('SIGINT'));process.on('SIGTERM',()=>close('SIGTERM'));
